from pathlib import Path
import re

ROOT=Path('.')

def fn(s,n,c):
    m=re.search(r'(?m)^\s*(?:(?:public|private|internal|protected)\s+)?(?:suspend\s+)?fun\s+'+re.escape(n)+r'\b',s)
    if not m: raise RuntimeError('missing '+n)
    b=s.find('{',m.end()); d=0
    if b<0: raise RuntimeError('no body '+n)
    for i in range(b,len(s)):
        if s[i]=='{': d+=1
        elif s[i]=='}':
            d-=1
            if d==0: return s[:m.start()]+c.rstrip()+s[i+1:]
    raise RuntimeError('unbalanced '+n)

